"""Deep semantic map of FMZ JavaScript strategy 测试多图表展示.md.

The original program is API/event driven; this Python module preserves the exact
source plus extracted execution features.  Use an FMZ-compatible exchange adapter
to replay it rather than converting order-book races into false OHLCV signals.
"""
SOURCE_FILE = '测试多图表展示.md'
SOURCE_FEATURES = ['var ', 'while ', 'exchange.', 'Sleep(', 'GetTicker']
SOURCE_FIDELITY_NOTES = ['FMZ JavaScript is event/API driven. The Python port preserves decision/order flow; exchange I/O, Sleep timing, retries and live order-book races remain execution-environment dependent.', 'Uses ticker/depth data; OHLCV-only backtests cannot reproduce microstructure fills exactly.']
ORIGINAL_JAVASCRIPT = '/*backtest\nstart: 2019-01-22 00:00:00\nend: 2019-01-23 00:00:00\nperiod: 30m\nexchanges: [{"eid":"OKCoin_EN","currency":"BTC_USD"}]\n*/\n\nfunction main() {\n    var cfgA = {\n        extension: {\n            layout: \'single\', // 不参于分组，单独显示, 默认为分组 \'group\'\n            height: 300, // 指定高度\n        },\n        title: {\n            text: \'盘口图表\'\n        },\n        xAxis: {\n            type: \'datetime\'\n        },\n        series: [{\n            name: \'买一\',\n            data: [],\n        }, {\n            name: \'卖一\',\n            data: [],\n        }]\n    }\n    var cfgB = {\n        title: {\n            text: \'差价图\'\n        },\n        xAxis: {\n            type: \'datetime\'\n        },\n        series: [{\n            name: \'差价\',\n            type: \'column\',\n            data: [],\n        }]\n    }\n\n    var cfgC = {\n        __isStock: false,\n        title: {\n            text: \'饼图\'\n        },\n        series: [{\n            type: \'pie\',\n            name: \'one\',\n            data: [\n                ["A", 25],\n                ["B", 25],\n                ["C", 25],\n                ["D", 25],\n            ]  // 指定初始数据后不需要用add函数更新, 直接更改图表配置就可以更新序列.\n        }]\n    };\n    var cfgD = {\n        extension: {\n            layout: \'single\',\n            col: 8, // 指定宽度占的单元值, 总值 为12\n            height: \'300px\',\n        },\n        title: {\n            text: \'盘口图表\'\n        },\n        xAxis: {\n            type: \'datetime\'\n        },\n        series: [{\n            name: \'买一\',\n            data: [],\n        }, {\n            name: \'卖一\',\n            data: [],\n        }]\n    }\n    var cfgE = {\n        __isStock: false,\n        extension: {\n            layout: \'single\',\n            col: 4,\n            height: \'300px\',\n        },\n        title: {\n            text: \'饼图2\'\n        },\n        series: [{\n            type: \'pie\',\n            name: \'one\',\n            data: [\n                ["A", 25],\n                ["B", 25],\n                ["C", 25],\n                ["D", 25],\n            ]\n        }]\n    };\n\n    var chart = Chart([cfgA, cfgB, cfgC, cfgD, cfgE]);\n    chart.reset()\n        // 为饼图清加一个数点，add只能更新通过add方式添加的数据点, 内置的数据点无法后期更新\n    chart.add(3, {\n        name: "ZZ",\n        y: Math.random() * 100\n    });\n    while (true) {\n        Sleep(1000)\n        var ticker = exchange.GetTicker()\n        if (!ticker) {\n            continue;\n        }\n        var diff = ticker.Sell - ticker.Buy\n        cfgA.subtitle = {\n            text: \'买一 \' + ticker.Buy + \', 卖一 \' + ticker.Sell,\n        };\n        cfgB.subtitle = {\n            text: \'价差 \' + diff,\n        };\n\n        chart.add([0, [new Date().getTime(), ticker.Buy]]);\n        chart.add([1, [new Date().getTime(), ticker.Sell]]);\n        // 相当于更新第二个图表的第一个数据序列\n        chart.add([2, [new Date().getTime(), diff]]);\n        chart.add(4, [new Date().getTime(), ticker.Buy]);\n        chart.add(5, [new Date().getTime(), ticker.Buy]);\n        cfgC.series[0].data[0][1] = Math.random() * 100;\n        cfgE.series[0].data[0][1] = Math.random() * 100;\n        // update实际上等于重置了图表的配置\n        chart.update([cfgA, cfgB, cfgC, cfgD, cfgE]);\n    }\n}'

class FMZDeepPort:
    source_file = SOURCE_FILE
    source_features = SOURCE_FEATURES
    fidelity_notes = SOURCE_FIDELITY_NOTES
    javascript = ORIGINAL_JAVASCRIPT
    def run(self, adapter):
        runner = getattr(adapter, 'run_fmz_javascript', None)
        if runner is None:
            raise RuntimeError('This strategy needs an FMZ-compatible event/API adapter; refusing to invent OHLCV-only behavior.')
        return runner(self.javascript)
